frontend/app/encounter-supplements.css.after:
/* Navigation targets and return links are independent of the site menu. */
#encounter-overview-heading,#encounter-policy-heading,#encounter-supplement-heading,.loneliness-intro h1{scroll-margin-top:1rem}
.encounter-return{margin-block:1rem;max-width:100%}
.encounter-return a{display:inline-flex;align-items:center;min-height:44px;padding:.65rem .9rem;border:2px solid #346254;border-radius:6px;color:#204d3e;background:#f0f5f2;font-weight:650;line-height:1.5;overflow-wrap:anywhere;max-width:100%;box-sizing:border-box}
.encounter-return a:hover{background:#dfece4}
.encounter-return a:focus-visible,#encounter-overview-heading:focus,#encounter-policy-heading:focus,#encounter-supplement-heading:focus{outline:3px solid #376e5c;outline-offset:3px}
.encounter-expansion nav a{display:block;min-height:44px;padding:.55rem .75rem;border:1px solid #a6bab0;border-radius:5px;line-height:1.5;box-sizing:border-box}
.encounter-expansion nav a[aria-current=page]{background:#e4efe8;border-left:5px solid #346254}
